package checks;
import java.lang.reflect.*;import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.resources.ResourceLocation;import com.raiiiden.warborn.client.shader.ShaderRegistry;import com.raiiiden.warborn.client.util.NvgClient2;
public class FilterChecks{
 static int count;static void ok(boolean b,String s){count++;if(!b)throw new AssertionError(s);}static Object pain;static Method update;static Field request;static Minecraft mc;
 static void medical()throws Exception{update.invoke(pain,mc);}static void requested(boolean b)throws Exception{request.setBoolean(null,b);}
 static void loop(ShaderRegistry reg,int n)throws Exception{for(int i=0;i<n;i++){NvgClient2.frame();medical();}}
 public static void main(String[]a)throws Exception{boolean old=a[0].equals("old");mc=Minecraft.getInstance();ShaderRegistry reg=ShaderRegistry.getInstance();Class<?> probe=Class.forName("checks.NativePainProbe");pain=probe.getConstructor().newInstance();update=probe.getDeclaredMethod("updateEffect",Minecraft.class);update.setAccessible(true);Field strength=probe.getDeclaredField("painStrength");strength.setAccessible(true);strength.setFloat(pain,1f);request=NvgClient2.class.getDeclaredField("visionRequested");request.setAccessible(true);String[] modes={"nvg","snvg","dvg","tvg","twvg","tbvg"};for(String mode:modes)reg.registerShader(mode,ResourceLocation.fromNamespaceAndPath("fracturepoint","shaders/post/"+mode+".json"),x->false,p->{});
 requested(false);mc.player.helmet.open=true;medical();ok(mc.gameRenderer.currentEffect().getName().contains("firstaid"),"medical post filter works with visor raised");int before=mc.gameRenderer.loads;for(int i=0;i<500;i++)medical();ok(mc.gameRenderer.loads==before,"ordinary pain filter stable");
 mc.player.helmet.open=false;requested(true);reg.setShaderEnabled("nvg",true);before=mc.gameRenderer.loads;loop(reg,120);
 if(old){ok(mc.gameRenderer.loads-before>=200,"original medical/NVG shaders repeatedly recreate their chains");ok(mc.gameRenderer.currentEffect().getName().contains("firstaid"),"original pain filter steals displayed helmet filter");System.out.println("BASELINE_FILTER_CHECKS="+count+"; repeated loads="+(mc.gameRenderer.loads-before));return;}
 ok(mc.gameRenderer.loads-before==1,"lowering visor loads native filter once despite injury");ok(mc.gameRenderer.currentEffect().getName().contains("fracturepoint"),"helmet filter remains displayed after medical update");
 for(String mode:modes){for(String id:modes)reg.setShaderEnabled(id,false);reg.setShaderEnabled(mode,true);before=mc.gameRenderer.loads;loop(reg,1000);ok(mc.gameRenderer.loads-before==1,"one load per native filter selection "+mode);ok(mc.gameRenderer.currentEffect().getName().endsWith(mode+".json"),"selected native mode preserved "+mode);}
 PostChain healthy=mc.gameRenderer.effect;before=mc.gameRenderer.loads;strength.setFloat(pain,1.85f);loop(reg,1000);ok(mc.gameRenderer.effect==healthy&&mc.gameRenderer.loads==before,"being shot does not replace or rebuild helmet shader");
 mc.gameRenderer.effect=null;loop(reg,1000);ok(mc.gameRenderer.loads==before+1,"lost shader/resource reload recovered exactly once");
 requested(false);mc.player.helmet.open=true;for(String mode:modes)reg.setShaderEnabled(mode,false);before=mc.gameRenderer.loads;medical();ok(mc.gameRenderer.loads==before+1&&mc.gameRenderer.effect.getName().contains("firstaid"),"raising visor restores medical post filter");for(int i=0;i<1000;i++)medical();ok(mc.gameRenderer.loads==before+1,"medical shader remains stable after leaving NVG");
 mc.player.helmet.open=false;requested(true);reg.setShaderEnabled("dvg",true);loop(reg,1000);ok(mc.gameRenderer.effect.getName().endsWith("dvg.json"),"next activation shows new digital filter");requested(false);for(String mode:modes)reg.setShaderEnabled(mode,false);medical();ok(mc.gameRenderer.effect.getName().contains("firstaid"),"battery/deactivation returns post slot to medical filter");
 mc.player=null;ok(!NvgClient2.ownsPostEffect(),"disconnect releases slot even before client tick");System.out.println("PATCHED_FILTER_CHECKS="+count+"; no repeated loads across 9000+ simulated frames");}}
